arguments.file_text:
@namespace sv_20d9e4127e074137ab56522e219533d9.Components.Pages.Settings
@using sv_20d9e4127e074137ab56522e219533d9.Services
@inject ISettingsService SettingsService

<div class="appearance-section">
    @if (_loading)
    {
        <p class="loading">Loading appearance settings...</p>
    }
    else
    {
        <div class="setting-group">
            <h3>Theme</h3>
            <div class="radio-group">
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    <label class="radio-item">
                        <input type="radio" name="theme" value="@theme"
                               checked="@(_theme == theme)"
                               @onchange="() => _theme = theme" />
                        <span>@theme</span>
                    </label>
                }
            </div>
        </div>

        <div class="setting-group">
            <h3>Font Size</h3>
            <div class="radio-group">
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="@size"
                               checked="@(_fontSize == size)"
                               @onchange="() => _fontSize = size" />
                        <span>@size</span>
                    </label>
                }
            </div>
        </div>

        <div class="setting-group">
            <h3>Language</h3>
            <select @bind="_language">
                <option value="en">English</option>
                <option value="es">Español</option>
                <option value="fr">Français</option>
                <option value="de">Deutsch</option>
                <option value="ja">日本語</option>
                <option value="zh">中文</option>
            </select>
        </div>

        <div class="setting-group">
            <h3>Compact Mode</h3>
            <label class="toggle-item">
                <input type="checkbox" @bind="_compactMode" />
                <span>Enable compact layout</span>
            </label>
        </div>

        <!-- Live Preview -->
        <div class="preview-area @GetPreviewClasses()">
            <h4>Live Preview</h4>
            <div class="preview-content">
                <p class="preview-heading">Sample Heading</p>
                <p class="preview-text">This is how your content will look with the selected settings. The theme, font size, and compact mode are reflected here.</p>
                <button class="preview-button">Sample Button</button>
            </div>
        </div>

        <div class="form-actions">
            <button class="btn-primary" @onclick="SaveAsync" disabled="@_saving">
                @(_saving ? "Saving..." : "Save")
            </button>
        </div>

        @if (_showSuccess)
        {
            <div class="toast success">Appearance settings saved!</div>
        }
    }
</div>

@code {
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;
    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = $"theme-{_theme.ToLowerInvariant()} font-{_fontSize.ToLowerInvariant()}";
        if (_compactMode) classes += " compact";
        return classes;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _saving = false;
        _showSuccess = true;
        _ = HideToastAsync();
    }

    private async Task HideToastAsync()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

.appearance-section {
    max-width: 600px;
}

.setting-group {
    margin-bottom: 1.5rem;
}

.setting-group h3 {
    margin: 0 0 0.5rem 0;
    font-size: 1rem;
    color: #333;
}

.radio-group {
    display: flex;
    gap: 1.25rem;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
    padding: 0.4rem 0.75rem;
    border: 1px solid #ddd;
    border-radius: 4px;
}

.radio-item:has(input:checked) {
    border-color: #1976d2;
    background: #e3f2fd;
}

.toggle-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
}

select {
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
    min-width: 200px;
}

/* Live Preview */
.preview-area {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 1.25rem;
    margin: 1.5rem 0;
    transition: all 0.3s ease;
}

.preview-area h4 {
    margin: 0 0 0.75rem 0;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #999;
}

.preview-content {
    transition: all 0.3s ease;
}

.preview-heading {
    font-weight: 700;
    margin: 0 0 0.5rem 0;
}

.preview-text {
    margin: 0 0 0.75rem 0;
    line-height: 1.5;
}

.preview-button {
    padding: 0.4rem 1rem;
    border-radius: 4px;
    border: none;
    cursor: pointer;
    font-weight: 500;
}

/* Theme variants */
.preview-area.theme-light {
    background: #ffffff;
    color: #333;
}

.preview-area.theme-light .preview-button {
    background: #1976d2;
    color: white;
}

.preview-area.theme-dark {
    background: #1e1e2e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-area.theme-dark .preview-button {
    background: #64b5f6;
    color: #1e1e2e;
}

.preview-area.theme-system {
    background: #f5f5f5;
    color: #333;
}

.preview-area.theme-system .preview-button {
    background: #546e7a;
    color: white;
}

/* Font size variants */
.preview-area.font-small .preview-content {
    font-size: 0.8rem;
}

.preview-area.font-small .preview-heading {
    font-size: 1rem;
}

.preview-area.font-medium .preview-content {
    font-size: 0.95rem;
}

.preview-area.font-medium .preview-heading {
    font-size: 1.2rem;
}

.preview-area.font-large .preview-content {
    font-size: 1.1rem;
}

.preview-area.font-large .preview-heading {
    font-size: 1.4rem;
}

/* Compact mode */
.preview-area.compact .preview-content {
    line-height: 1.2;
}

.preview-area.compact .preview-text {
    margin-bottom: 0.4rem;
}

.preview-area.compact {
    padding: 0.75rem;
}

.form-actions {
    margin-top: 1.5rem;
}

.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
}

.toast.success {
    background: #d4edda;
    color: #155724;
    border: 1px solid #c3e6cb;
}

.loading {
    color: #666;
    font-style: italic;
}

