@page "/settings"
@using sv_20d9e4127e074137ab56522e219533d9.Components.Pages.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="section => _activeSection = section" />

    <main class="settings-content">
        <h2>@_activeSection</h2>

        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </main>
</div>

@code {
    private string _activeSection = "Profile";
}

.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 60px);
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    overflow: hidden;
    margin: 1rem;
    background: white;
}

.settings-content {
    flex: 1;
    padding: 2rem;
}

.settings-content h2 {
    margin: 0 0 1.5rem 0;
    font-size: 1.5rem;
    color: #222;
    border-bottom: 1px solid #eee;
    padding-bottom: 0.75rem;
}

