                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </main>
</div>

@code {
    private string _activeSection = "Profile";
}

.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 60px);
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    overflow: hidden;
    margin: 1rem;
    background: white;
}

.settings-content {
    flex: 1;
    padding: 2rem;
}

.settings-content h2 {
    margin: 0 0 1.5rem 0;
    font-size: 1.5rem;
    color: #222;
    border-bottom: 1px solid #eee;
    padding-bottom: 0.75rem;
}

/* Shared button styles */
:deep(.btn-primary) {
    padding: 0.5rem 1.25rem;
    background: #1976d2;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
    font-weight: 500;
}

:deep(.btn-primary:hover) {
    background: #1565c0;
}

:deep(.btn-primary:disabled) {
    background: #90caf9;
    cursor: not-allowed;
}

:deep(.btn-secondary) {
    padding: 0.5rem 1.25rem;
    background: white;
    color: #333;
    border: 1px solid #ccc;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

:deep(.btn-secondary:hover) {
    background: #f5f5f5;
}

